select
c.*
,n.bill_company_id billCompanyId
from billing_apply_company c
left join survey_consignor n on c.entrust_org_id = n.id
where 1 = 1 and c.delete_flag = 0

    and c.company_name like CONCAT(CONCAT('%',#{companyName,jdbcType=VARCHAR}), '%')


    and c.id = #{id,jdbcType=BIGINT}


    and c.entrust_org_id = #{entrustOrgId}


    and c.state = #{state}

order by c.id desc

    limit #{pageIndex}, #{pageSize}

select
count(1)
from billing_apply_company where 1 = 1 and delete_flag = 0

    and company_name like CONCAT(CONCAT('%',#{companyName,jdbcType=VARCHAR}), '%')


    and id = #{id,jdbcType=BIGINT}


    and entrust_org_id = #{entrustOrgId}


    and state = #{state}

select

from billing_apply_company
where 1 = 1

    and company_name = #{companyName,jdbcType=VARCHAR}


    and entrust_org_id = #{entrustOrgId}


    and state = #{state}

limit 1
